import java.nio.file.*;import java.util.*;
final class Phase3PreservationSupport {
 private static Properties allowed,assets;private static final Map<String,byte[]> archive=new HashMap<>();private static final Map<String,String> historicalHashes=new HashMap<>();
 static synchronized Properties allowed()throws Exception{if(allowed==null)allowed=Phase10PreservationSupport.properties("docs/PHASE3_AUTHORIZED.properties");return allowed;}
 static byte[] previous(String path,byte[] now){try{now=Phase4PreservationSupport.previous(path,now);String expected=allowed().getProperty(path);if(expected==null)return now;byte[] before=archive.get(path);if(before==null){before=Phase10PreservationSupport.archive(path,"PHASE3");archive.put(path,before);}String hash=ForestPreservationSupport.hash(now);if(hash.equals(expected))return before;if(hash.equals(ForestPreservationSupport.hash(before)))return now;
 // Older guards can encounter their own already-projected immutable revision.
 for(String prefix:List.of("PHASE2_UI","PHASE1_WORLD","CINEMATIC_PACING","TREE_COLLISION","TOWN_FINAL_FIXES","PHASE10_6C","PHASE10_6B","PHASE10_5_1","PHASE10_5","PHASE10_3","PHASE10_2F","PHASE10_2BE","PHASE10_1","PHASE10","PHASE9_4","PHASE9_3_2B","PHASE9_3_1_1","PHASE9_3_1","PHASE9_2_1","PHASE9_2","QUEST_FLOW","JOURNEY_HOME","FINAL_CHAPTER","VILLAGE_INTEGRATION","VILLAGE_ACTIVITIES","SANTA_BASE_STORY","SANTA_BASE","FOREST_OVERHAUL","GAMEPLAY_OVERHAUL")){String key=path+"@"+prefix,oldHash=historicalHashes.get(key);if(oldHash==null){byte[] old=Phase10PreservationSupport.archive(path,prefix);oldHash=old==null?"":ForestPreservationSupport.hash(old);historicalHashes.put(key,oldHash);}if(hash.equals(oldHash))return now;}throw new AssertionError("Unreviewed Phase3 revision "+path);
 }catch(Exception e){throw new AssertionError(e);}}
 static synchronized Set<String> assets()throws Exception{if(assets==null){assets=Phase10PreservationSupport.properties("docs/PHASE3_ASSETS.properties");for(String p:assets.stringPropertyNames())if(!p.startsWith("assets/vfx/phase3/")||!ForestPreservationSupport.hash(Files.readAllBytes(Path.of(p))).equals(assets.getProperty(p)))throw new AssertionError("Unreviewed Phase3 artwork "+p);}return assets.stringPropertyNames();}
}
